#include <iostream>
#include <fstream>
#include <memory>

class FileOpener {
public:
  FileOpener(const std::string& filename) : file_(new std::ofstream(filename)) {
    if (!*file_) {
      throw std::runtime_error("Could not open file");
    }
  }
  ~FileOpener() {
    if (file_) {
      file_->close();
      delete file_;
    }
  }
  std::ofstream* getStream() { return file_; }
private:
  std::ofstream* file_;
};

void processFile(const std::string& filename) {
  try {
    FileOpener file(filename);
    *file.getStream() << "This is some data.";
    // ... further file operations ...
  } catch (const std::runtime_error& e) {
    std::cerr << "Error: " << e.what() << std::endl;
  }
}

int main() {
  processFile("mydata.txt");
  return 0;
}
